using Microsoft.CodeAnalysis;
using Nextended.CodeGen.Config;
using Nextended.CodeGen.Contracts;
using Nextended.CodeGen.Generators.TypescriptGeneration;
using Shouldly;
using static Nextended.CodeGen.Tests.TestCompilation;

namespace Nextended.CodeGen.Tests;

/// <summary>
/// The member order of generated files does not depend on the order the compilation got its files in (IDE, command line, incremental build):
/// a type declared in several files lists its members by file (the files of a folder before its subfolders), then by position.
/// </summary>
[TestClass]
public class MemberOrderTests
{
    private const string Entity = """
        using System;
        using Nextended.Core.Attributes;
        namespace Shop.Domain;

        public abstract partial class Entity { public Guid Id { get; set; } }

        [AutoGenerateDto]
        public partial class Shipment : Entity
        {
            public string Number { get; set; } = "";
            public decimal Weight { get; set; }
        }
        """;

    // a second part of the entity and its base in another folder (like an EF configuration next to the entity)
    private const string Tags = """
        using System;
        using System.Collections.Generic;
        namespace Shop.Domain;

        public abstract partial class Entity { public DateTime CreatedUtc { get; set; } }

        public partial class Shipment { public List<string> Tags { get; set; } = []; }
        """;

    // a third part in the project folder itself
    private const string Root = """
        namespace Shop.Domain;
        public partial class Shipment { public string? Zone { get; set; } }
        """;

    private static DtoGenerationConfig Config() => new()
    {
        Namespace = "Shop.Contracts",
        CreateFileHeaders = false,
        CreateRegions = false,
        CreateComments = false
    };

    /// <summary>The compilation with the given sources at the given paths, in the order given, plus the in-tree attribute sources.</summary>
    private static Compilation Arranged(params (string Path, string Source)[] files)
    {
        var compilation = CompileWithInTreeAttributes();
        return compilation.RemoveAllSyntaxTrees().AddSyntaxTrees(files.Select(f => Parse(f.Source, f.Path)).Concat(compilation.SyntaxTrees));
    }

    private static readonly (string, string)[] Files =
    [
        (@"C:\src\Shop\Model\Domain\Shipment.cs", Entity),
        (@"C:\src\Shop\Persistence\ShipmentTags.cs", Tags),
        (@"C:\src\Shop\Shipment.Zone.cs", Root)
    ];

    private static IEnumerable<(string, string)[]> Permutations()
    {
        yield return Files;
        yield return [Files[1], Files[0], Files[2]];
        yield return [Files[2], Files[1], Files[0]];
        yield return [Files[1], Files[2], Files[0]];
    }

    private static List<(string FileName, string Content)> Dtos(Compilation compilation, string? profile = null)
    {
        if (profile != null)
            compilation = compilation.AddSyntaxTrees(Parse(profile, @"C:\src\Shop\CodeGen.cs"));
        var (files, diagnostics) = GenerateWithDiagnostics(compilation, Config());
        diagnostics.Where(d => d.Severity >= DiagnosticSeverity.Warning).ShouldBeEmpty();
        return files.Select(f => (f.FileName, f.Content)).ToList();
    }

    private static void InOrder(string text, params string[] members)
    {
        var positions = members.Select(m => text.IndexOf($" {m} {{", StringComparison.Ordinal)).ToList();
        positions.ShouldAllBe(p => p >= 0, text);
        positions.ShouldBe(positions.OrderBy(p => p).ToList(), string.Join(", ", members) + Environment.NewLine + text);
    }

    private static string Class(IEnumerable<(string FileName, string Content)> files, string file, string name)
    {
        var content = files.Single(f => f.FileName == file).Content;
        return content.Substring(content.IndexOf("class " + name, StringComparison.Ordinal));
    }

    [TestMethod]
    public void Partial_members_keep_their_order_whatever_order_the_compilation_has_its_files_in()
    {
        var expected = Dtos(Arranged(Files));
        foreach (var files in Permutations())
            Dtos(Arranged(files)).ShouldBe(expected);

        // the project folder's file first, then the folders by name; by position within a file
        InOrder(Class(expected, "ShipmentDto.g.cs", "ShipmentDto"), "Zone", "Number", "Weight", "Tags");
    }

    [TestMethod]
    public void Repeated_runs_give_the_same_files()
    {
        var compilation = Arranged(Files);
        Dtos(compilation).ShouldBe(Dtos(compilation));
    }

    [TestMethod]
    public void Base_members_Order_and_OrderLast_are_applied_to_the_stable_order_and_keep_ties_in_it()
    {
        const string profile = """
            using Nextended.Core.CodeGen;
            using Shop.Domain;

            public sealed class Ordering : CodeGenConfig
            {
                public Ordering()
                {
                    Dto<Shipment>(d => d.View("ShipmentRow", v => v.BaseMembersFirst().Order(x => x.Weight).OrderLast(x => x.Id)));
                }
            }
            """;
        var expected = Dtos(Arranged(Files), profile);
        foreach (var files in Permutations())
            Dtos(Arranged(files), profile).ShouldBe(expected);

        // Weight first, Id last; between them the base members (by file), then the own members (by file), each in the stable order
        InOrder(Class(expected, "ShipmentRowDto.g.cs", "ShipmentRowDto"), "Weight", "CreatedUtc", "Zone", "Number", "Tags", "Id");
    }

    [TestMethod]
    public void TypeScript_members_of_partial_types_keep_their_order()
    {
        const string dto = """
            namespace Shop.Contracts;
            public partial class ShipmentDto { public string Number { get; set; } = ""; public decimal Weight { get; set; } }
            """;
        const string tags = """
            namespace Shop.Contracts;
            public partial class ShipmentDto { public string[] Tags { get; set; } = []; }
            """;
        var config = new TypescriptGenerationConfig { IncludeNamespaces = ["Shop"], Barrel = false };
        var a = TypescriptGenerator.Generate(Arranged((@"C:\src\Shop\Contracts\ShipmentDto.cs", dto), (@"C:\src\Shop\Tags\ShipmentDto.cs", tags)), config).Files;
        var b = TypescriptGenerator.Generate(Arranged((@"C:\src\Shop\Tags\ShipmentDto.cs", tags), (@"C:\src\Shop\Contracts\ShipmentDto.cs", dto)), config).Files;

        b.ShouldBe(a);
        var text = a.Values.Single(v => v.Contains("ShipmentDto"));
        text.IndexOf("weight", StringComparison.Ordinal).ShouldBeLessThan(text.IndexOf("tags", StringComparison.Ordinal), text);
    }
}
